typedef float vm_num_t;
typedef long long big_int;

extern "C" unsigned int strlen(const char *);
extern float __fsqrt(float);

class stringx;
class string_buf {
  friend class stringx;
  friend stringx operator+(const char *, const stringx &);
  friend stringx operator+(const stringx &, const char *);
  big_int *data;
  int ref_count;
  int char_length;
};

class stringx {
  friend stringx operator+(const char *, const stringx &);
  friend stringx operator+(const stringx &, const char *);
  char *chars;
  string_buf *my_buf;
public:
  stringx();
  stringx(const stringx &);
  ~stringx();
  void make_room(int);
  void append(const char *, int = -1);
  void append(const stringx &);
};

inline stringx operator+(const char *lhs, const stringx &rhs)
{
  stringx foo;
  int len = strlen(lhs);
  foo.make_room(len + rhs.my_buf->char_length);
  foo.append(lhs, len);
  foo.append(rhs);
  return foo;
}

inline stringx operator+(const stringx &lhs, const char *rhs)
{
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}

class script_object {
public:
  class instance {
    stringx name;
  public:
    const stringx &get_name() const { return name; }
  };
};

class vm_executable {
  void *owner;
  stringx name;
  stringx fullname;
public:
  const stringx &get_fullname() const { return fullname; }
};

class vm_thread {
  script_object::instance *inst;
  const vm_executable *ex;
public:
  script_object::instance *get_instance() const { return inst; }
  const vm_executable *get_executable() const { return ex; }
};

class vm_stack {
public:
  int salloc;
  char *buffer;
  char *SP;
private:
  vm_thread *my_thread;
public:
  char *get_SP() const { return SP; }
  vm_thread *get_thread() const { return my_thread; }
  void pop(int n) { SP += -n; }
  bool push(const char *, int);
};

struct vector3d {
  float x;
  float y;
  float z;
  float xy_length() const { return (float)__fsqrt(x*x + y*y); }
};

extern void error(const stringx &);

class script_library_class {
public:
  class function {
  public:
    enum entry_t { FIRST_ENTRY };
  };
};

class slf_vector3d_xy_norm_t {
public:
  struct parms_t {
    vector3d me;
  };
  bool operator()(vm_stack& stack, script_library_class::function::entry_t entry);
};

bool slf_vector3d_xy_norm_t::operator()(vm_stack& stack, script_library_class::function::entry_t entry)
{
  stack.pop(sizeof(parms_t));
  parms_t* parms = (parms_t*)stack.get_SP();
  vm_num_t result = parms->me.xy_length();
  if (!stack.push((char*)&result,sizeof(result)) )
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() );
  return true;
}
